INSERT INTO permissions(code) SELECT unnest(ARRAY['constitution.view','constitution.manage','constitution.approve','cycle.view','cycle.manage','officer.view','officer.manage']) ON CONFLICT(code) DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='SUPER_ADMIN' AND p.code IN ('constitution.view','constitution.manage','constitution.approve','cycle.view','cycle.manage','officer.view','officer.manage') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code IN ('PROJECT_ADMIN','STATE_COORDINATOR') AND p.code IN ('constitution.view','constitution.manage','constitution.approve','cycle.view','cycle.manage','officer.view','officer.manage','group.activate') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='FACILITATOR' AND p.code IN ('constitution.view','constitution.manage','cycle.view','cycle.manage','officer.view','officer.manage') ON CONFLICT DO NOTHING;
